#!/usr/bin/env bash
# Terraform state migration generated by avmigrate.
#
# Converting a resource into a module changes its Terraform address. Without
# moving state, the next plan destroys and recreates every migrated resource.
#
# BACK UP STATE FIRST:
#     terraform state pull > terraform.tfstate.backup.$(date +%s)
#
# Run `terraform init` before this script so the modules are present.

set -euo pipefail

# ---------------------------------------------------------------------
# 2 resource(s) can be moved directly: the AVM module stores
# them with the same azurerm resource type, so the move is lossless.
# ---------------------------------------------------------------------

# azurerm_log_analytics_workspace.platform  ->  avm-res-operationalinsights-workspace
terraform state mv 'azurerm_log_analytics_workspace.platform' 'module.log_analytics_workspace_platform.azurerm_log_analytics_workspace.this[0]'

# azurerm_network_security_group.application  ->  avm-res-network-networksecuritygroup
terraform state mv 'azurerm_network_security_group.application' 'module.application.azurerm_network_security_group.this[0]'

# ---------------------------------------------------------------------
# 3 resource(s) CANNOT be moved with `terraform state mv`.
# These AVM modules are built on AzAPI, so the resource is stored as
# `azapi_resource`. Terraform refuses a move between different resource
# types ("resource types don't match"), so they must be re-imported.
#
# RECOMMENDED: use Microsoft's Terraform State Importer, which discovers
# the resource IDs from Azure Resource Graph rather than making you find
# them by hand:
#     https://github.com/Azure/terraform-state-importer
# A starter config has been generated: terraform-state-importer.config.yaml
#
# Offline fallback: avm-state-import.tf.disabled
# ---------------------------------------------------------------------

# azurerm_resource_group.platform -> module.platform.azapi_resource.this[0]  (import - see terraform-state-importer.config.yaml)
# azurerm_storage_account.application -> module.storage_account_application.azapi_resource.this[0]  (import - see terraform-state-importer.config.yaml)
# azurerm_virtual_network.platform -> module.virtual_network_platform.azapi_resource.vnet  (import - see terraform-state-importer.config.yaml)

# ---------------------------------------------------------------------
# Absorbed sub-resources. These became entries in a parent module's typed
# input, so the target address is keyed by the map key shown below.
# Confirm the exact address with `terraform plan` before running these.
# ---------------------------------------------------------------------

# terraform state mv 'azurerm_subnet.application' 'module.<parent>.module.subnets["application"].<INTERNAL>'

echo
echo 'State move complete. Run `terraform plan` and confirm it reports no
echo 'changes before applying.'
